sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_completion;
uniform float amzp_cfLen;
uniform float amzp_noiseZoom;
uniform float amzp_noiseAmt;
uniform float amzp_noiseType;
uniform float amzp_dirMode;
uniform float amzp_reverse;
uniform float amzp_fillMode;
layout(color) uniform half4 amzp_fillCol;
uniform float amzp_fillStr;
uniform float amzp_seed;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float th1(float x) { x = clamp(x, -15.0, 15.0); float e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float3 th3(float3 x) { x = clamp(x, -15.0, 15.0); float3 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float4 th4(float4 x) { x = clamp(x, -15.0, 15.0); float4 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_aSpeed * 0.5) : p; }
    float2 advFC() {
        float2 W = layer;
        float2 q = amzLayerNorm() * W - 0.5 * W;
        q = advRot(q, radians(amzp_advAngle)) / max(amzp_advScale, 0.01);
        return q + 0.5 * W;
    }
    float2 toL(float2 I) {
        float2 W = layer;
        float2 q = advRot((I - 0.5 * W) * max(amzp_advScale, 0.01), -radians(amzp_advAngle));
        return (q + 0.5 * W) / W;
    }
    float2 toP(float2 uv) { float2 W = layer; return (advRot((uv - 0.5) * W, radians(amzp_advAngle)) / max(amzp_advScale, 0.01)) / W + 0.5; }
    float2 fromP(float2 pu) { float2 W = layer; return advRot((pu - 0.5) * W * max(amzp_advScale, 0.01), -radians(amzp_advAngle)) / W + 0.5; }
    float3 unpre(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    float hsh(float2 p) { float3 p3 = fract(float3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
    float vn(float2 p) { float2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hsh(i + amzp_seed), hsh(i + float2(1.0, 0.0) + amzp_seed), f.x), mix(hsh(i + float2(0.0, 1.0) + amzp_seed), hsh(i + float2(1.0, 1.0) + amzp_seed), f.x), f.y); }
    float nz(float2 p) {
        if (int(amzp_noiseType) == 1) return hsh(floor(p * 40.0) + amzp_seed);
        if (int(amzp_noiseType) == 2) return hsh(floor(p * 2.0) + amzp_seed);
        return vn(p) * 0.55 + vn(p * 2.03 + 7.1) * 0.3 + vn(p * 4.1 + 3.3) * 0.15;
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float C = clamp(prog(amzp_completion), 0.0, 1.0);
        if ((amzp_autop>0.5)) C = fract(prog(amzp_completion));
        if ((amzp_reverse>0.5)) C = 1.0 - C;
        float2 uv = toP(amzLayerNorm());
        float asp = W.x / W.y;
        float v;
        if (int(amzp_dirMode) == 0) v = uv.x;
        else if (int(amzp_dirMode) == 1) v = 1.0 - uv.x;
        else if (int(amzp_dirMode) == 2) v = uv.y;
        else if (int(amzp_dirMode) == 3) v = 1.0 - uv.y;
        else { float d = length((uv - 0.5) * float2(asp, 1.0)) / (0.5 * length(float2(asp, 1.0))); v = int(amzp_dirMode) == 4 ? d : 1.0 - d; }
        float L = max(amzp_cfLen, 0.0);
        float pr = C * (1.0 + L + amzp_noiseAmt * 0.5) - L;
        float mask = smoothstep(v - L - 0.0001, v, pr);
        float n = nz(uv * float2(asp, 1.0) * 6.0 * amzp_noiseZoom);
        float m = clamp(mask + (n - 0.5) * amzp_noiseAmt * mask * (1.0 - mask) * 4.0 + n * mask * amzp_noiseAmt * 0.5, 0.0, 1.0);
        if (C <= 0.0) m = 0.0;
        if (C >= 1.0) m = 1.0;
        float4 lay = orig;
        float4 fc = int(amzp_fillMode) == 0 ? float4(amzp_fillCol.rgb, 1.0) : float4(0.0);
        float4 R = mix(lay, fc, m * (int(amzp_fillMode) == 0 ? amzp_fillStr : 1.0));
        amzOutput = R;
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }
    void amzRender() {
        nmMain();
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
